const fs = require('fs');

function main() {
    const input = fs.readFileSync(0, 'utf-8');
    let pos = 0;

    function nextInt() {
        while (pos < input.length && input.charCodeAt(pos) <= 32) {
            pos++;
        }
        if (pos >= input.length) return null;
        let res = 0;
        while (pos < input.length && input.charCodeAt(pos) > 32) {
            res = res * 10 + (input.charCodeAt(pos) - 48);
            pos++;
        }
        return res;
    }

    const T = nextInt();
    if (T === null) return;
    const N = nextInt();

    const X = new Float64Array(N);
    for (let i = 0; i < N; i++) {
        X[i] = nextInt();
    }

    X.sort();

    let minNeighborhood = (X[0] + X[1]) / 2.0;

    for (let i = 1; i < N - 1; i++) {
        const size = (X[i + 1] - X[i - 1]) / 2.0;
        if (size < minNeighborhood) {
            minNeighborhood = size;
        }
    }

    const lastSize = T - (X[N - 2] + X[N - 1]) / 2.0;
    if (lastSize < minNeighborhood) {
        minNeighborhood = lastSize;
    }

    console.log(minNeighborhood.toFixed(2));
}

main();
